def balance_repair_crews(loads, crews):
    size = len(loads)
    if crews > size:
        return -1
    totals = [0]
    running = 0
    for load in loads:
        running += load
        totals.append(running)
    previous = totals
    for groups in range(2, crews + 1):
        current = []
        for end in range(size + 1):
            value = None
            for cut in range(groups - 1, end):
                last_zone = totals[end] - totals[cut]
                candidate = previous[cut]
                if last_zone > candidate:
                    candidate = last_zone
                if value is None or candidate < value:
                    value = candidate
            current.append(value)
        previous = current
    return previous[size]
